package com.clas.service; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.clas.entity.*; import com.clas.mapper.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Service public class RiderMetricsService { private final RiderProfileMapper profiles; private final RiderDailyMetricMapper metrics; private final OrdersMapper orders; private final RiderReviewMapper reviews; private final DeliveryExceptionMapper exceptions;
 public RiderMetricsService(RiderProfileMapper profiles,RiderDailyMetricMapper metrics,OrdersMapper orders,RiderReviewMapper reviews,DeliveryExceptionMapper exceptions){this.profiles=profiles;this.metrics=metrics;this.orders=orders;this.reviews=reviews;this.exceptions=exceptions;}
 @Scheduled(cron="0 10 0 * * *",zone="Asia/Shanghai") @Transactional public void archiveYesterday(){archive(LocalDate.now(ZoneId.of("Asia/Shanghai")).minusDays(1));}
@Transactional public void archive(LocalDate day){LocalDateTime from=day.atStartOfDay(),to=day.plusDays(1).atStartOfDay();for(RiderProfile p:profiles.selectList(new LambdaQueryWrapper<RiderProfile>().eq(RiderProfile::getStatus,"APPROVED"))){if(metrics.selectCount(new LambdaQueryWrapper<RiderDailyMetric>().eq(RiderDailyMetric::getRiderId,p.getUserId()).eq(RiderDailyMetric::getMetricDate,day))>0)continue;List<Orders> done=orders.selectList(new LambdaQueryWrapper<Orders>().eq(Orders::getRiderId,p.getUserId()).eq(Orders::getDeliveryStatus,"DELIVERED").ge(Orders::getDeliveryCompletedAt,from).lt(Orders::getDeliveryCompletedAt,to));int count=done.size(), income=done.stream().mapToInt(x->x.getRiderCommission()==null?0:x.getRiderCommission()).sum();List<RiderReview> rs=reviews.selectList(new LambdaQueryWrapper<RiderReview>().eq(RiderReview::getRiderId,p.getUserId()).ge(RiderReview::getCreatedAt,from).lt(RiderReview::getCreatedAt,to));double rating=rs.isEmpty()?4d:rs.stream().mapToInt(RiderReview::getScore).average().orElse(4d);int late=exceptions.selectCount(new LambdaQueryWrapper<DeliveryException>().eq(DeliveryException::getRiderId,p.getUserId()).eq(DeliveryException::getExceptionType,"OVERDUE").ge(DeliveryException::getCreatedAt,from).lt(DeliveryException::getCreatedAt,to)).intValue();double base=Math.min(100,40*(1d-Math.min(1,late/(double)Math.max(1,count)))+25*(rating/5d)+15*Math.min(1,count/20d)+10*Math.min(1,income/10000d)+10);double finalScore=Math.max(0,base-late*5);RiderDailyMetric m=new RiderDailyMetric();m.setRiderId(p.getUserId());m.setMetricDate(day);m.setCompletedOrders(count);m.setNetIncome(income);m.setAverageRating(BigDecimal.valueOf(rating));m.setOverdueCount(late);m.setAverageDeliveryMinutes(0);m.setBaseScore(BigDecimal.valueOf(base));m.setManualAdjustment(BigDecimal.ZERO);m.setFinalScore(BigDecimal.valueOf(finalScore));m.setGrade(finalScore>=90?"A":finalScore>=80?"B":finalScore>=60?"C":"D");m.setArchivedAt(LocalDateTime.now());metrics.insert(m);}}
}
